"""Demo mode: full exploration without an account, and strict separation from real families."""
import asyncio, subprocess, sys, time, json
sys.path.insert(0, 'tests')
from playwright.async_api import async_playwright
src = open('tests/journey.py').read().split('async def main')[0]; exec(src)   # reuse helpers: ctx, check, route, signup_family, create_dinner, toast
API = ('/rest/v1/', '/auth/v1/', '/functions/v1/')

async def main():
    srv = subprocess.Popen([sys.executable, 'tests/standin_server.py', 'dist', '8787']); time.sleep(0.8)
    try:
        async with async_playwright() as pw:
            b = await pw.chromium.launch(args=['--no-sandbox'])
            # ---------- flow 1: anonymous visitor tries the demo on a phone ----------
            c, p = await ctx(b, True); hits = []
            await p.goto(BASE + '/'); await p.wait_for_selector('[data-act="demoStart"]')
            check('welcome offers both: create my family + try demo', await p.locator('[data-act="authStart"][data-mode="signup"]').count() == 1 and await p.locator('[data-act="demoStart"]').count() == 1)
            p.on('request', lambda r: hits.append(r.url) if any(a in r.url for a in API) else None)
            await p.click('[data-act="demoStart"]'); await p.wait_for_selector('.demo-badge')
            check('demo opens without an account, demo badge visible', await p.locator('.demo-badge').count() == 1 and await p.locator('#au-email').count() == 0)
            check('sample family has 2 dinners', await p.locator('.evrow').count() == 2)
            await p.click('[data-act="go"][data-to="family"]'); await p.wait_for_timeout(200)
            check('sample family members listed (17)', await p.locator('.plist .prow').count() == 17)
            await p.click('[data-act="go"][data-to="home"]'); await p.locator('.evrow').first.click(); await p.wait_for_selector('.big-n')
            check('sample dinner: 17 people, 14 voted, 3 connected tables', (await p.inner_text('.big-n')).replace('\n', '') == '14/17' and '3 שולחנות' in await p.inner_text('#main'), await p.inner_text('.big-n'))
            # vote as a family member who hasn't voted, with the assistant's help
            await p.click('[data-act="voteLocal"]'); await p.locator('[data-act="voteMe"]:has-text("ליה")').click(); await p.wait_for_selector('[data-act="chatOpen"]')
            await p.click('[data-act="chatOpen"]'); await p.fill('#chat-in', 'אני רוצה לשבת ליד גיל ומאיה'); await p.press('#chat-in', 'Enter')
            await p.wait_for_selector('[data-act="chatAction"]', timeout=4000)
            await p.locator('[data-act="chatAction"]').last.click(); await p.click('[data-act="modalClose"]')
            check('assistant suggested names and selection needs a tap (not auto-submitted)', len(await p.locator('.slot.full').all()) == 2)
            await p.click('[data-act="voteSubmit"]'); await p.click('[data-act="confirmOk"]'); await p.wait_for_selector('[data-act="voteExit"]')
            await p.click('[data-act="voteExit"]'); await p.wait_for_selector('.big-n')
            check('demo vote counted (15/17)', (await p.inner_text('.big-n')).replace('\n', '') == '15/17')
            await p.click('[data-act="generate"]'); await p.wait_for_selector('#seatplan', timeout=15000); await p.wait_for_timeout(3300)
            check('smart seating generated (20 seats)', await p.locator('#seatplan [data-chair]').count() == 20)
            before = await p.evaluate("JSON.stringify(S.store.events[0].plan.assignment)")
            await p.locator('#seatplan [data-chair]').nth(2).click(); await p.wait_for_selector('select[data-in="swapWith"]')
            await p.select_option('select[data-in="swapWith"]', index=4); await p.wait_for_timeout(300)
            check('experimenting with seats works', before != await p.evaluate("JSON.stringify(S.store.events[0].plan.assignment)"))
            await p.click('[data-act="mode3d"][data-ctx="seat"][data-v="1"]')
            await p.wait_for_function("document.querySelectorAll('.v3d-labels .lbl').length === 17", timeout=8000)
            check('3D table shows all 17 names', True)
            await p.click('[data-act="publish"]'); await p.wait_for_selector('.present-card', timeout=12000)
            check('presentation runs in demo (no real link produced)', await p.locator('.present-card [data-act="copy"]').count() == 0)
            await p.click('[data-act="presentClose"]')
            await p.click('[data-act="go"][data-to="home"]'); await p.locator('.evrow').nth(1).click(); await p.wait_for_selector('.big-n')
            check('past dinner already has a seating plan', await p.locator('[data-act="openSeating"]').count() == 1)
            # reset
            await p.click('[data-act="demoReset"]'); await p.click('[data-act="confirmOk"]'); await p.locator('.evrow').first.click(); await p.wait_for_selector('.big-n')
            check('reset restores the original demo (14/17, no plan)', (await p.inner_text('.big-n')).replace('\n', '') == '14/17' and await p.locator('[data-act="openSeating"]').count() == 0)
            check('demo made ZERO requests to database, auth or functions', not hits, hits[:3])
            ls = await p.evaluate("Object.keys(localStorage)")
            prod = await p.evaluate("localStorage.getItem('mazleg:prod:v1') || ''")
            check('demo stored only under its own key; real storage holds no demo data', 'mazleg:demo:v1' in ls and 'demo-' not in prod, ls)
            await p.click('[data-act="demoOwn"]'); await p.wait_for_selector('#au-email')
            check('"Start my own family" leaves the demo and opens real sign-up', await p.locator('.demo-badge').count() == 0)
            await p.fill('#au-email', 'new@real.test'); await p.fill('#au-pass', 'correct-horse-9'); await p.click('[data-act="authSubmit"]')
            await p.wait_for_selector('#fam-name'); await p.fill('#fam-name', 'משפחה אמיתית'); await p.click('[data-act="famCreate"]'); await p.wait_for_selector('.fam-bar')
            ws = await p.evaluate("sb.rpc('get_workspace', {p_family: S.family.id}).then(r => r.data)")
            check('new real family starts empty — no demo data leaked', ws['events'] == [] and ws['members'] == [], (len(ws['events']), len(ws['members'])))
            # ---------- flow 2: a real organizer dips into the demo and comes back ----------
            ca, pa = await ctx(b); await signup_family(pa, 'omer@a.test', 'משפחת עומר')
            await create_dinner(pa, 'ארוחה אמיתית', ['אמיתי' + str(i) for i in range(1, 6)])
            await pa.click('[data-act="go"][data-to="home"]'); await pa.wait_for_timeout(300)
            hits2 = []; pa.on('request', lambda r: hits2.append(r.url) if any(a in r.url for a in API) else None)
            await pa.click('[data-act="demoStart"]'); await pa.wait_for_selector('.demo-badge')
            check('real organizer sees only demo data inside the demo', 'ארוחה אמיתית' not in await pa.inner_text('#main') and await pa.locator('.evrow').count() == 2)
            r = await pa.evaluate("sb.rpc('get_workspace', {p_family: (S.real.family||{}).id}).then(r => r.error && r.error.message)")
            check('inside the demo even the organizer\u2019s own workspace calls are blocked', r == 'demo_mode', r)
            await pa.locator('.evrow').first.click(); await pa.click('[data-act="delEvent"]'); await pa.click('[data-act="confirmOk"]'); await pa.wait_for_timeout(1200)
            check('demo session made no API requests', not hits2, hits2[:3])
            await pa.click('[data-act="demoExit"]'); await pa.wait_for_selector('.fam-bar')
            check('exit returns to the real workspace intact', 'ארוחה אמיתית' in await pa.inner_text('#main') and await pa.locator('.evrow').count() == 1)
            ws = await pa.evaluate("sb.rpc('get_workspace', {p_family: S.family.id}).then(r => r.data)")
            check('server copy of the real family untouched by the demo', [e['name'] for e in ws['events']] == ['ארוחה אמיתית'] and not any(e['id'].startswith('demo') for e in ws['events']))
            errs = p.errs + pa.errs; check('no JavaScript errors', not errs, errs[:3])
            await b.close()
    finally:
        srv.terminate()
    print(f"\n{sum(ok for _, ok in results)}/{len(results)} demo checks passed")
asyncio.run(main())
